    DIAGRAM_FORMAT,
    JIRA_FIELDS,
    SUMMARY_MAX_LENGTH,
    JIRA_SUMMARY_MAX_LENGTH,
    truncateSummary,
    DEFAULT_CONFLUENCE,
    DEFAULT_FORMATS,
    resolveStatuses
