    var withLabel = String(jiraCfg.stageFallback || '').toLowerCase() === 'label';
    var ado = String(trackerProvider || '').toLowerCase() === 'ado';
    return String(jql).replace(/\{stage\.([A-Za-z0-9_]+)(?::([^}]*))?\}/g, function (match, key, literal) {
