    if (ticket && ticket.labels) {
        const labels = Array.isArray(ticket.labels) ? ticket.labels : (ticket.labels.value || []);
        for (var i = 0; i < labels.length; i++) {
            if (/_(wip|draft)$/i.test(labels[i]) || /^(wip|draft)$/i.test(labels[i])) {
                return true;
            }
        }
    }
    return false;
}

