        var decision = readDecisionJson();
        if (!decision) {
            tracker.postComment(ticketKey, 'h3. ⚠️ Bug Creation Error\n\nCould not read bug_decision.json. Check workflow logs.');
            try { tracker.removeLabel(ticketKey, wipLabel); } catch (e) {}
