            'h4. Linked bugs\n\n' +
            bugs.map(function(b) { return '* ' + b.key + ' — ' + (b.fields && b.fields.summary || ''); }).join('\n') + '\n\n' +
            '_Bugs are excluded from individual bug_development while they are in this batch._';

