            .indexOf("labels = 'stage_in_review_passed'") !== -1);
    });

    test('unknown stage key with no literal is left untouched', function() {
        assert.equal(configLoaderModule.interpolateJql("x {stage.NOPE} y", cfg()), "x {stage.NOPE} y");
    });

