/**
 * Recover Jira tickets whose GitHub PR was already merged while Jira stayed in
 * a review/rework status.
 */

const { LABELS } = require('./config.js');
var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

function prMatchesTicket(pr, ticketKey) {
    if (!pr || !ticketKey) return false;
    var titleMatch = pr.title && pr.title.indexOf(ticketKey) !== -1;
    var branchMatch = pr.head && pr.head.ref && pr.head.ref.indexOf(ticketKey) !== -1;
    return !!(titleMatch || branchMatch);
}

function isMergedPR(pr) {
    if (!pr) return false;
    return !!(pr.merged_at || pr.mergedAt || pr.merge_commit_sha || pr.mergeCommit) ||
        pr.state === 'MERGED' ||
        pr.merged === true;
}

function findMergedPRForTicket(scm, ticketKey) {
    try {
        var open = scm.listPrs('open') || [];
        for (var openIndex = 0; openIndex < open.length; openIndex++) {
            if (prMatchesTicket(open[openIndex], ticketKey)) {
                console.log('Open PR still exists for ' + ticketKey + ', skipping merged-PR recovery: #' + open[openIndex].number);
                return null;
            }
        }
    } catch (openError) {
        console.warn('Could not list open PRs for merged recovery guard:', openError.message || openError);
        return null;
    }

    var closed = [];
    try {
        closed = scm.listPrs('closed') || [];
    } catch (e) {
        console.warn('Could not list closed PRs:', e.message || e);
        return null;
    }

    for (var i = 0; i < closed.length; i++) {
        if (prMatchesTicket(closed[i], ticketKey) && isMergedPR(closed[i])) {
            return closed[i];
        }
    }
    return null;
}

function removeLabel(ticketKey, label) {
    if (!ticketKey || !label) return;
    try {
        getTracker().removeLabel(ticketKey, label);
        console.log('Removed label from Jira:', label);
    } catch (e) {}
}

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    if (!ticketKey) {
        console.error('No ticket key provided');
        return { success: false, action: 'missing_ticket' };
    }

    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = config.jira;
    initTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
    var scm = scmModule.createScm(config);
    var pr = findMergedPRForTicket(scm, ticketKey);

    if (!pr) {
        console.log('No merged PR found for', ticketKey);
        return { success: true, action: 'none' };
    }

    var prNumber = pr.number || pr.id || '?';
    var prUrl = pr.html_url || pr.url || '';
    console.log('Recovered merged PR #' + prNumber + ' for ' + ticketKey);

    try {
        getTracker().moveToStatus(ticketKey, jiraConfig.statuses.MERGED);
        console.log('Moved', ticketKey, 'to', jiraConfig.statuses.MERGED);
    } catch (e) {
        console.warn('Could not move ticket to Merged:', e.message || e);
    }

    removeLabel(ticketKey, LABELS.PR_APPROVED);
    removeLabel(ticketKey, 'sm_pr_merge_triggered');
    removeLabel(ticketKey, 'sm_story_review_triggered');
    removeLabel(ticketKey, 'sm_story_rework_triggered');

    try {
        getTracker().postComment(ticketKey, 'h3. ✅ Merged PR Recovered\n\n' +
                'Found already merged PR #' + prNumber + (prUrl ? ' — [View PR|' + prUrl + ']' : '') +
                '. Ticket moved to *' + jiraConfig.statuses.MERGED + '* so the normal post-merge pipeline can continue.');
    } catch (e) {}

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run.
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }

    return { success: true, action: 'moved_to_merged', prNumber: prNumber };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, findMergedPRForTicket, prMatchesTicket, isMergedPR };
}

/**
 * Check Task Stories Done — postJSAction for task_done_check agent.
 *
 * Runs on every SM cycle for each intake/in-development Task.
 * Finds all linked Stories/Bugs and checks if they are all Done.
 *
 * - If all linked Stories/Bugs are Done → moves the Task to "Ready For Testing".
 * - If no linked Stories/Bugs exist yet → releases lock (intake may still be running).
 * - Otherwise → removes the SM idempotency label so the SM re-triggers
 *   this check on the next cycle.
 */

const configLoader = require('./configLoader.js');
const trackersModule = require('./common/trackers.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');

function action(params) {
    const ticketKey = params.ticket && params.ticket.key;
    const customParams = params.jobParams && params.jobParams.customParams;
    const removeLabel = customParams && customParams.removeLabel;
    const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    const jiraConfig = projectConfig.jira;
    const tracker = trackersModule.createTracker(projectConfig, customParams || {});

    function releaseLock() {
        if (ticketKey && removeLabel) {
            try {
                tracker.removeLabel(ticketKey, removeLabel);
                console.log('Released SM label — will re-check next cycle');
            } catch (e) {
                console.warn('Failed to remove SM label:', e);
            }
        }
    }

    try {
        if (!ticketKey) throw new Error('params.ticket.key is missing');
        console.log('=== Task done check for', ticketKey, '===');

        // JQL text: provider-specific query (WIQL on ado)
        // Step 1: Count all linked Stories and Bugs
        const allItems = tracker.searchIssues('issue in linkedIssues("' + ticketKey + '") AND issuetype in (Story, Bug)', { maxResults: 100 }) || [];
        const totalItems = allItems.length;
        console.log('Linked Stories + Bugs:', totalItems);

        if (totalItems === 0) {
            console.log('No linked Stories or Bugs found — releasing lock, will re-check next cycle');
            releaseLock();
            return { success: true, action: 'no_stories', ticketKey };
        }

        // Step 2: Find linked Stories/Bugs NOT yet Done
        const notDoneItems = tracker.searchIssues('issue in linkedIssues("' + ticketKey + '") AND issuetype in (Story, Bug) AND status != "' + jiraConfig.statuses.DONE + '"', { maxResults: 1 }) || [];
        const notDoneCount = notDoneItems.length;
        console.log('Stories/Bugs not yet Done:', notDoneCount, '/', totalItems);

        if (notDoneCount > 0) {
            console.log('Not all Stories/Bugs done — releasing lock, will re-check next cycle');
            releaseLock();
            return { success: true, action: 'waiting', total: totalItems, notDone: notDoneCount, ticketKey };
        }

        // Step 3: All Stories/Bugs Done → move Task to Ready For Testing
        console.log('All', totalItems, 'Story/Bug(s) done — moving', ticketKey, 'to Ready For Testing');

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.READY_FOR_TESTING);

        tracker.postComment(ticketKey, 'h3. ✅ Task Complete — All Stories & Bugs Done\n\n' +
                'All *' + totalItems + '* linked Story/Bug(s) are in *Done* status.\n\n' +
                'The task has been automatically moved to *Ready For Testing*.'
        );

        console.log('✅ Task', ticketKey, 'moved to Ready For Testing');

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return { success: true, action: 'moved_to_ready_for_testing', total: totalItems, ticketKey };

    } catch (error) {
        console.error('❌ Error in checkTaskStoriesDone:', error);
        releaseLock();
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

