function loadMoveToInTesting(mocks) {
    mocks = mocks || {};
    return (function (_m) { return loadModule('js/moveToInTesting.js', makeRequire(Object.assign({}, {
        './config.js': configModule,
        './configLoader.js': makeDefaultConfigLoaderMock(),
