function moveToInTestingCapturingLogs(mocks) {
    var logs = [];
    var warns = [];
    var withConsole = Object.assign({
        console: {
            log: function(msg) { logs.push(String(msg)); },
            warn: function(msg) { warns.push(String(msg)); }
        }
    }, mocks || {});
    return {
        module: loadMoveToInTesting(withConsole),
        logs: logs,
        warns: warns
