        assert.deepEqual(added, [{ key: 'TS-210', label: 'stage_ready_for_testing' }]);
        assert.ok(x.logs.some(function(l) { return l.indexOf('✅ Moved TS-210 to Ready For Testing') !== -1; }), 'success log printed for the marked stage');
