            ticket: { key: 'TS-60' },
            jobParams: { customParams: { stageFallback: 'label', removeLabel: 'sm_story_done_check_triggered' } }
        });

        assert.equal(result.action, 'waiting_in_flight');
        assert.deepEqual(moved, [], 'nothing is moved while a TC is in flight');
    });

