        var moved = [];
        var module = loadCheckStoryTestsPassed({
            jira_search_by_jql: function(args) {
                if (args.jql.indexOf('issuetype = "Test Case"') !== -1) {
                    return [storyGh916Tc('TS-63', 'New', ['stage_passed']), storyGh916Tc('TS-64', 'New', ['stage_skipped'])];
