    });

    var threw = null;
    try {
        m.mergeMain('PROJ-999', { workingDir: null, git: TEST_CONFIG.git });
    } catch (e) {
        threw = e;
    }

    assert.ok(threw, 'must refuse');
    assert.contains(threw.toString(), 'conclude', 'error must tell the operator what to do');
});

