            : 'status in (' + quotedName + ')';
        if (!withLabel) return statusClause;
        var label = DEFAULT_CONFIG.stageLabel(key);
        var labelClause = ado
            ? "[System.Tags] CONTAINS '" + label + "'"
            : "labels = '" + label + "'";
        return '(' + statusClause + ' OR ' + labelClause + ')';
    });
}

