// github_create_comment directly. Memoised per owner/repo: a tick makes dozens of writes.
var _githubTrackers = {};
function githubTracker(owner, repo) {
    var k = String(owner || '') + '/' + String(repo || '');
    if (!_githubTrackers[k]) _githubTrackers[k] = trackersModule.createGithubTracker(owner, repo);
    return _githubTrackers[k];
}

function smTracker(config) {
    var cfg = config || projectConfig || {};
    var cp = (RUN_JOB_PARAMS && RUN_JOB_PARAMS.customParams) || {};
    return trackersModule.createTracker(cfg, cp);
}

function moveStatus(ticketKey, targetStatus) {
    try {
        if (DRY) { console.log('  [dry] 🔀 ' + ticketKey + ' → ' + targetStatus); }
        else { smTracker().moveToStatus(ticketKey, targetStatus); }
        console.log('  ✅ ' + ticketKey + ' → ' + targetStatus);
    } catch (e) {
        console.warn('  ⚠️  Status transition failed for ' + ticketKey + ': ' + (e.message || e));
    }
}

function hasLabel(ticket, label) {
    if (!label) return false;
    // State items from the sources are flattened ({labels: [...]}); raw Jira
    // ticket objects keep them under fields.labels.
    var labels = ticket.labels ||
        ((ticket.fields && ticket.fields.labels) ? ticket.fields.labels : []);
    return labels.indexOf(label) !== -1;

