        // default query is byte-identical to the old literal; anything else (spaces, dashes) is quoted so a
        // configured multi-word status cannot break the query.
        return /^[A-Za-z0-9_]+$/.test(value) ? value : '"' + value.replace(/"/g, '\\"') + '"';
