            ? fields.status.name : null);
    if (statusName !== undefined && status === statusName) return true;
    if (stageFallback !== 'label') return false;
    return _labelNames(ticket.labels || fields.labels || []).indexOf(_stageLabel(stageKey)) !== -1;
