var TAG_ONLY_STAGE_KEYS = {
    PASSED: true,
    FAILED: true,
    IN_REVIEW_PASSED: true,
    IN_REVIEW_FAILED: true,
    SKIPPED: true,
    IRRELEVANT: true,
    BUG_TO_FIX: true,
    IN_TESTING: true,
